async function init(){renderNav();await refresh(true);if(!state.appTimersStarted){state.appTimersStarted=true;setInterval(()=>refresh(false),8000);setInterval(loadTasks,2500);setInterval(liveRefreshCurrentPage,4000)}}
function renderNav(){const html=pages.map(p=>`<div class="nav-item ${state.page===p[0]?"active":""}" onclick="go('${p[0]}')">${icon(p[1])}<span class="nav-text">${p[2]}</span></div>`).join("");$("#nav").innerHTML=`<button class="side-collapse" onclick="toggleSidebar()" title="\u6536\u8d77 / \u5c55\u5f00\u4fa7\u8fb9\u680f">${icon("menu")}<span id="collapseText">${state.sidebarCollapsed?"\u5c55\u5f00":"\u6536\u8d77"}</span></button>`+html+`<div class="side-spacer"></div>`;$("#bottomNav").innerHTML=pages.slice(0,5).map(p=>`<div class="nav-item ${state.page===p[0]?"active":""}" onclick="go('${p[0]}')">${icon(p[1])}<span class="nav-text">${p[2]}</span></div>`).join("");$("#collapseText")&&($("#collapseText").textContent=state.sidebarCollapsed?"\u5c55\u5f00":"\u6536\u8d77");renderThemeButton() }
