function toggleDrawer(){$(".sidebar").classList.toggle("open")}function toggleSidebar(){state.sidebarCollapsed=!state.sidebarCollapsed;document.documentElement.classList.toggle("sidebar-collapsed",state.sidebarCollapsed);localStorage.sidebarCollapsed=String(state.sidebarCollapsed);renderNav()}
