function setThemeMode(mode){state.themeMode=["light","dark"].includes(mode)?mode:resolvedTheme();applyTheme();closeThemeMenu();toast(state.themeMode==="dark"?"\u5df2\u5207\u6362\u6df1\u8272\u6a21\u5f0f":"\u5df2\u5207\u6362\u6d45\u8272\u6a21\u5f0f")}
